'use strict';

/**
* BLAS level 1 routine to compute the dot product `x^H * y` of `x` and `y`.
*
* @module @stdlib/blas/base/cdotc
*
* @example
* var Complex64Array = require( '@stdlib/array/complex64' );
* var Complex64 = require( '@stdlib/complex/float32/ctor' );
* var cdotc = require( '@stdlib/blas/base/cdotc' );
*
* var x = new Complex64Array( [ 7.0, -8.0, -1.0, -9.0 ] );
* var y = new Complex64Array( [ 6.0, -6.0, -9.0, 5.0 ] );
* var z = cdotc( x.length, x, 1, y, 1 );
* // returns <Complex64>[ 54.0, -80.0 ]
*
* @example
* var Complex64Array = require( '@stdlib/array/complex64' );
* var Complex64 = require( '@stdlib/complex/float32/ctor' );
* var cdotc = require( '@stdlib/blas/base/cdotc' );
*
* var x = new Complex64Array( [ 7.0, -8.0, -1.0, -9.0 ] );
* var y = new Complex64Array( [ 6.0, -6.0, -9.0, 5.0 ] );
*
* var z = cdotc.ndarray( x.length, x, 1, 0, y, 1, 0 );
* // returns <Complex64>[ 54.0, -80.0 ]
*/

// MODULES //

var join = require( 'path' ).join;
var tryRequire = require( '@stdlib/utils/try-require' );
var isError = require( '@stdlib/assert/is-error' );
var main = require( './main.js' );


// MAIN //

var cdotc;
var tmp = tryRequire( join( __dirname, './native.js' ) );
if ( isError( tmp ) ) {
	cdotc = main;
} else {
	cdotc = tmp;
}


// EXPORTS //

module.exports = cdotc;

// exports: { "ndarray": "sdot.ndarray" }
